<script setup>
import {computed, nextTick, onBeforeUnmount, onMounted, reactive, ref, watch} from 'vue';
import PlaceCard from './PlaceCard.vue';
import places from './data/places.json';
import {filterPlaces,readStore,today,unique} from './lib.js';
const route=ref(location.hash.slice(1)||'explore');
const filters=reactive({search:'',continent:'',country:'',province:'',city:'',category:''});
const continents=['亚洲','欧洲','非洲','北美洲','南美洲','大洋洲'];
const categories=[{value:'',name:'全部风景',icon:'✳'},{value:'自然风光',name:'自然风光',icon:'△'},{value:'古迹',name:'历史古迹',icon:'▥'},{value:'人文',name:'人文风情',icon:'⌘'}];
const knownIds=new Set(places.map(p=>p.id));
const saved=ref(readStore('roam:saved:v1',[],d=>Array.isArray(d)&&d.every(id=>typeof id==='string')).filter(id=>knownIds.has(id)));
const journals=ref(readStore('roam:journals:v1',[],d=>Array.isArray(d)&&d.every(j=>j&&typeof j.id==='string'&&knownIds.has(j.placeId)&&typeof j.title==='string'&&typeof j.body==='string'&&typeof j.date==='string')));
const toast=ref(''); let toastTimer;
const modal=ref(null); const confirmDelete=ref(''); const editor=ref(null);const importFile=ref(null);let previousFocus;
const draft=reactive({id:'',placeId:places[0].id,title:'',date:today(),body:''});
const formError=ref('');const pageSize=ref(8);
const current=computed(()=>places.find(p=>route.value===`place/${p.id}`));
const isDetail=computed(()=>route.value.startsWith('place/'));
const isSaved=computed(()=>route.value==='saved');const isJournal=computed(()=>route.value==='journal');
const hero=places[0];
const countries=computed(()=>unique(places.filter(p=>!filters.continent||p.continent===filters.continent),'country'));
const provinces=computed(()=>unique(places.filter(p=>(!filters.continent||p.continent===filters.continent)&&(!filters.country||p.country===filters.country)),'province'));
const cities=computed(()=>unique(places.filter(p=>(!filters.continent||p.continent===filters.continent)&&(!filters.country||p.country===filters.country)&&(!filters.province||p.province===filters.province)),'city'));
const filtered=computed(()=>filterPlaces(isSaved.value?places.filter(p=>saved.value.includes(p.id)):places,filters));
const related=computed(()=>current.value?places.filter(p=>p.id!==current.value.id&&p.category===current.value.category).slice(0,3):[]);
const myNotes=computed(()=>current.value?journals.value.filter(j=>j.placeId===current.value.id):[]);
const countryCount=unique(places,'country').length;
function notify(message){toast.value=message;clearTimeout(toastTimer);toastTimer=setTimeout(()=>toast.value='',3200);}
function persist(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true;}catch{notify('浏览器存储不可用，请先导出备份或释放空间。');return false;}}
function toggleSave(id){const next=saved.value.includes(id)?saved.value.filter(x=>x!==id):[...saved.value,id];if(persist('roam:saved:v1',next)){saved.value=next;notify(next.includes(id)?'已收藏，把这处风景留给未来。':'已取消收藏。');}}
function resetFilters(){Object.assign(filters,{search:'',continent:'',country:'',province:'',city:'',category:''});}
function selectContinent(c){filters.continent=c;filters.country='';filters.province='';filters.city='';}
function changeCountry(){filters.province='';filters.city='';}
let exploreAfterNavigation=false;
function scrollToDestinations(){nextTick(()=>document.querySelector('#destinations')?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'}));}
function goExplore(){if(route.value==='explore'){scrollToDestinations();return;}exploreAfterNavigation=true;location.hash='explore';}
function search(){goExplore();}
function syncRoute(){route.value=location.hash.slice(1)||'explore';if(exploreAfterNavigation&&route.value==='explore'){exploreAfterNavigation=false;scrollToDestinations();}else{exploreAfterNavigation=false;window.scrollTo({top:0,behavior:'instant'});}}
watch(filters,()=>pageSize.value=8);
function openEditor(placeId=places[0].id,note=null){previousFocus=document.activeElement;Object.assign(draft,note||{id:'',placeId,title:'',date:today(),body:''});formError.value='';confirmDelete.value='';modal.value='editor';nextTick(()=>{editor.value?.showModal();editor.value?.querySelector('input')?.focus();});}
function openAbout(){previousFocus=document.activeElement;modal.value='about';nextTick(()=>editor.value?.showModal());}
function closeModal(){editor.value?.close();modal.value=null;nextTick(()=>previousFocus?.isConnected&&previousFocus.focus());}
function saveNote(){
 if(!draft.title.trim()||!draft.body.trim()||!draft.date){formError.value='请填写标题、日期和游记内容。';return;}
 const note={id:draft.id||crypto.randomUUID(),placeId:draft.placeId,title:draft.title.trim(),date:draft.date,body:draft.body.trim(),updatedAt:new Date().toISOString()};
 const next=draft.id?journals.value.map(j=>j.id===draft.id?note:j):[note,...journals.value];
 if(persist('roam:journals:v1',next)){journals.value=next;closeModal();notify('游记已保存在当前浏览器。');}
}
function deleteNote(id){if(confirmDelete.value!==id){confirmDelete.value=id;return;}const next=journals.value.filter(j=>j.id!==id);if(persist('roam:journals:v1',next)){journals.value=next;confirmDelete.value='';notify('游记已删除。');}}
function exportNotes(){const blob=new Blob([JSON.stringify({version:1,saved:saved.value,journals:journals.value},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=`山海漫游-备份-${today()}.json`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('备份已导出。');}
async function importNotes(event){const file=event.target.files?.[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error();const d=JSON.parse(await file.text());if(d.version!==1||!Array.isArray(d.saved)||!d.saved.every(id=>typeof id==='string'&&knownIds.has(id))||!Array.isArray(d.journals)||!d.journals.every(j=>j&&typeof j.id==='string'&&knownIds.has(j.placeId)&&typeof j.title==='string'&&j.title.length<=80&&typeof j.body==='string'&&j.body.length<=20000&&/^\d{4}-\d{2}-\d{2}$/.test(j.date)))throw Error();const nextSaved=[...new Set([...saved.value,...d.saved])];const nextNotes=[...journals.value];for(const note of d.journals)if(!nextNotes.some(n=>n.id===note.id))nextNotes.push(note);if(persist('roam:journals:v1',nextNotes)){journals.value=nextNotes;if(persist('roam:saved:v1',nextSaved))saved.value=nextSaved;notify('已合并导入收藏和游记。');}}catch{notify('无法导入：请选择山海漫游导出的有效备份。');}finally{event.target.value='';}}
function placeFor(id){return places.find(p=>p.id===id);}
onMounted(()=>window.addEventListener('hashchange',syncRoute));
onBeforeUnmount(()=>{window.removeEventListener('hashchange',syncRoute);clearTimeout(toastTimer);});
</script>

<template>
<header class="site-header"><a href="#explore" class="brand" aria-label="山海漫游首页"><svg class="brand-mark" viewBox="0 0 40 40" aria-hidden="true"><path d="m3 30 12-21 10 16 5-9 8 14H3Z"/><circle cx="30" cy="8" r="3"/></svg><span>山海漫游<small>ROAM & REMEMBER</small></span></a><nav aria-label="主导航"><a href="#explore" :class="{active:!isSaved&&!isJournal}"><span class="mobile-nav-icon">◎</span>探索世界</a><a href="#saved" :class="{active:isSaved}"><span class="mobile-nav-icon">♧</span>我的收藏<span v-if="saved.length" class="nav-count">{{saved.length}}</span></a><a href="#journal" :class="{active:isJournal}"><span class="mobile-nav-icon">▤</span>旅行手记</a></nav><button class="button primary header-write" @click="openEditor()"><span>＋</span> 写一篇游记</button></header>
<main>
<template v-if="!isDetail&&!isJournal">
<section v-if="!isSaved" class="hero"><img class="hero-image" :src="hero.image" alt="九寨沟五花海的蓝绿色湖水与山林" fetchpriority="high"/><div class="hero-shade"></div><div class="hero-content"><div class="overline"><span></span> THE WORLD IS A STORY. GO WRITE YOURS.</div><h1>山海之间，<br/>总有你的下一站<span>。</span></h1><p>去看辽阔的风景，也去遇见新的自己。<br class="mobile-only"/>让每一次出发，都有迹可寻。</p><form class="hero-search" @submit.prevent="search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/></svg><label class="sr-only" for="hero-query">搜索景点、国家或城市</label><input id="hero-query" v-model="filters.search" placeholder="你想去哪里？搜索景点、国家或城市"/><button type="submit">探索目的地 <span>↗</span></button></form><div class="hero-hints">灵感从这里开始 <button @click="filters.search='京都';search()">京都</button><button @click="filters.search='黄山';search()">黄山</button><button @click="filters.search='威尼斯';search()">威尼斯</button></div></div><a :href="`#place/${hero.id}`" class="hero-caption"><span class="caption-index">01 <i>/ {{places.length}}</i></span><span>此刻，想去的地方<strong>中国 · 四川 · 九寨沟 <b>↗</b></strong></span></a><div class="hero-bottom">SCROLL TO EXPLORE <span>↓</span></div></section>
<section v-if="isSaved" class="page-intro container"><div class="overline green">YOUR NEXT CHAPTER</div><h1>把喜欢的风景，<em>留给未来。</em></h1><p>这里藏着你的下一次出发。已收藏 {{saved.length}} 处目的地。</p></section>
<section id="destinations" class="discovery container"><div class="section-title"><div><div class="overline green">{{isSaved?'YOUR COLLECTION':'A LITTLE CURIOSITY, A BIG WORLD'}}</div><h2>{{isSaved?'我的心愿目的地':'下一站，去哪儿？'}}<span v-if="!isSaved" class="heading-dot">✳</span></h2></div><p v-if="!isSaved" class="section-aside">{{places.length}} 处精选目的地 / {{countryCount}} 个国家及跨国地区<br/>从熟悉的山川，到遥远的世界</p></div>
<div class="theme-tabs" role="group" aria-label="景点主题"><button v-for="c in categories" :key="c.name" :class="{selected:filters.category===c.value}" :aria-pressed="filters.category===c.value" @click="filters.category=c.value"><span>{{c.icon}}</span>{{c.name}}</button></div>
<div class="filters"><div class="continent-row"><span class="filter-label">目的地</span><div class="continent-options"><button :class="{selected:!filters.continent}" :aria-pressed="!filters.continent" @click="selectContinent('')">全部地区</button><button v-for="c in continents" :key="c" :class="{selected:filters.continent===c}" :aria-pressed="filters.continent===c" @click="selectContinent(c)">{{c}}</button></div></div><div class="region-row"><span class="filter-label">再近一点</span><div class="selects"><label><span class="sr-only">国家</span><select aria-label="国家" v-model="filters.country" @change="changeCountry"><option value="">全部国家／地区</option><option v-for="v in countries" :key="v">{{v}}</option></select></label><label><span class="sr-only">省／州</span><select aria-label="省／州" v-model="filters.province" @change="filters.city=''"><option value="">全部省／州</option><option v-for="v in provinces" :key="v">{{v}}</option></select></label><label><span class="sr-only">城市</span><select aria-label="城市" v-model="filters.city"><option value="">全部城市</option><option v-for="v in cities" :key="v">{{v}}</option></select></label></div><button class="reset-button" @click="resetFilters">↺ 重置</button></div></div>
<div class="results-bar"><span>为你找到 <strong>{{filtered.length}}</strong> 处{{filters.category||'心动'}}目的地<span v-if="filters.search"> · “{{filters.search}}” <button class="clear-search" aria-label="清除搜索" @click="filters.search=''">×</button></span></span><label class="list-search"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="10" cy="10" r="6"/><path d="m15 15 5 5"/></svg><span class="sr-only">筛选景点</span><input v-model="filters.search" placeholder="搜索风景、城市…"/></label></div>
<div v-if="filtered.length" class="places-grid"><PlaceCard v-for="p in filtered.slice(0,pageSize)" :key="p.id" :place="p" :saved="saved.includes(p.id)" @save="toggleSave"/></div>
<div v-else class="empty-state"><span class="empty-art">⌁</span><h3>{{isSaved&&!saved.length?'下一次出发，从一份喜欢开始':'还没找到这片风景'}}</h3><p>{{isSaved&&!saved.length?'点击景点图片上的书签，把心动的目的地放进收藏。':'试试其他关键词，或放宽地区与主题条件。'}}</p><a v-if="isSaved&&!saved.length" href="#explore" class="button primary">去探索世界 ↗</a><button v-else class="button primary" @click="resetFilters">清除筛选</button></div>
<div v-if="filtered.length>pageSize" class="load-more"><button class="button outline" @click="pageSize+=8">再看一些风景 <span>↓</span></button><small>已看 {{Math.min(pageSize,filtered.length)}} / {{filtered.length}} 处目的地</small></div><div v-else-if="filtered.length" class="end-note">— 风景会不断更新，故事等你来写 —</div>
</section><section v-if="!isSaved" class="journal-banner container"><div class="journal-illustration" aria-hidden="true">✎<span>POSTCARD<br/>FROM THE WORLD</span></div><div><div class="overline green">MAKE IT A MEMORY</div><h2>风景值得看见，<br class="mobile-only"/>旅途值得记住。</h2><p>写下一段文字，让路过的世界成为自己的故事。</p></div><button class="button primary" @click="openEditor()">写下我的第一篇 <span>↗</span></button></section>
</template>
<template v-else-if="isDetail&&current"><div class="container breadcrumb"><a href="#explore">探索世界</a><span>/</span>{{current.continent}}<span>/</span>{{current.name}}</div><section class="detail-hero container"><img :src="current.image" :alt="current.name"/><div class="detail-gradient"></div><div class="detail-title"><span class="overline">{{current.english.toUpperCase()}}</span><h1>{{current.name}}</h1><p>{{current.subtitle}}</p></div><span class="detail-category">{{current.category}}</span></section><div class="detail-layout container"><article class="detail-body"><div class="detail-location">◎ {{current.country}}<span>／</span>{{current.province}}<span>／</span>{{current.city}}</div><div class="card-tags"><span v-for="t in current.tags" :key="t">{{t}}</span></div><section><div class="overline green">THE STORY OF THIS PLACE</div><h2>关于这里</h2><p class="intro-text">{{current.intro}}</p></section><section><div class="overline green">TAKE A CLOSER LOOK</div><h2>值得停留的瞬间</h2><ol class="highlights"><li v-for="(h,i) in current.highlights" :key="h"><span>0{{i+1}}</span>{{h}}</li></ol></section><section><h2>我的旅行手记 <span class="muted">{{myNotes.length}}</span></h2><p v-if="!myNotes.length" class="muted">这里还没有你的故事，下一次出发后，记得回来写一笔。</p><div v-for="j in myNotes" :key="j.id" class="inline-note"><time>{{j.date}}</time><h3>{{j.title}}</h3><p>{{j.body}}</p><button class="text-button" @click="openEditor(current.id,j)">编辑手记 ↗</button></div><button class="text-button" @click="openEditor(current.id)">＋ 为这里写一篇游记</button></section><details class="source-panel"><summary>图片与文字来源 <span>＋</span></summary><p>{{current.textNote}}</p><p>介绍来源：<a :href="current.sourceUrl" target="_blank" rel="noopener noreferrer">UNESCO 世界遗产中心 ↗</a> · <a :href="current.textLicenseUrl" target="_blank" rel="noopener noreferrer">{{current.textLicense}}</a></p><p>摄影：{{current.photo.author}} · {{current.photo.license}}<br/><a :href="current.photo.page" target="_blank" rel="noopener noreferrer">原始照片与完整署名 ↗</a><span v-if="current.photo.licenseUrl"> · <a :href="current.photo.licenseUrl" target="_blank" rel="noopener noreferrer">图片许可 ↗</a></span></p><p class="muted">资料采集：{{current.collectedAt}}。图片作等比显示与裁切。地理分类用于浏览；具体开放信息请以景区官方公告为准。</p></details></article><aside class="journey-card"><span class="compass-art" aria-hidden="true">✳</span><div class="overline green">SAVE A LITTLE WANDERLUST</div><h2>给下一次出发，<br/>留一个位置。</h2><p>把向往的风景收好，<br/>等一个属于你的出发时刻。</p><button class="button primary" @click="toggleSave(current.id)">{{saved.includes(current.id)?'✓ 已在我的收藏':'＋ 收藏这个目的地'}}</button><button class="button outline" @click="openEditor(current.id)">为这里写一篇游记 ↗</button><small>收藏与手记保存在当前浏览器</small></aside></div><section class="related container"><div class="section-title"><div><div class="overline green">KEEP EXPLORING</div><h2>也许，你还想去</h2></div><a href="#explore" class="text-button">探索更多 ↗</a></div><div class="places-grid related-grid"><PlaceCard v-for="p in related" :key="p.id" :place="p" :saved="saved.includes(p.id)" @save="toggleSave"/></div></section></template>
<section v-else-if="isJournal" class="journal-page container"><div class="page-intro"><div class="overline green">MOMENTS WORTH KEEPING</div><h1>走过的路，<em>写成自己的故事。</em></h1><p>不必写得完美，记住当时的心情就好。</p></div><div class="journal-toolbar"><span>{{journals.length}} 篇旅行手记 <small>保存在本机浏览器</small></span><div><button class="text-button" @click="exportNotes">导出备份 ↓</button><button class="text-button" @click="importFile.click()">导入备份 ↑</button><input ref="importFile" class="sr-only" type="file" accept=".json,application/json" @change="importNotes"/><button class="button primary" @click="openEditor()">＋ 写游记</button></div></div><div v-if="!journals.length" class="empty-state journal-empty"><span class="empty-art">✎</span><h2>每段旅程，都值得一页纸。</h2><p>写下见过的风景、路上的小事，或一段不想忘记的心情。</p><button class="button primary" @click="openEditor()">写下第一篇手记 ↗</button></div><div v-else class="notes-list"><article v-for="j in journals" :key="j.id" class="note-card"><a :href="`#place/${j.placeId}`"><img :src="placeFor(j.placeId).image" :alt="placeFor(j.placeId).name"/></a><div><div class="overline green">{{j.date}} <span>· {{placeFor(j.placeId).name}}</span></div><h2>{{j.title}}</h2><p>{{j.body}}</p><div class="note-actions"><button class="text-button" @click="openEditor(j.placeId,j)">编辑手记 ↗</button><button class="text-button delete" @click="deleteNote(j.id)">{{confirmDelete===j.id?'确认删除？再次点击':'删除'}}</button><button v-if="confirmDelete===j.id" class="text-button" @click="confirmDelete=''">取消</button></div></div></article></div><p class="local-notice">手记仅保存在当前设备的浏览器中。清除网站数据会丢失记录，建议定期导出备份。</p></section>
<section v-else class="empty-state container"><h1>这处风景还未收录</h1><a href="#explore" class="button primary">回到探索世界</a></section>
</main>
<footer class="site-footer container"><a class="brand footer-brand" href="#explore"><span>山海漫游<small>ROAM & REMEMBER</small></span></a><p>世界很大，慢慢去看。<small>Made for the love of wandering.</small></p><button class="text-button" @click="openAbout">关于山海 · 内容来源 ↗</button></footer>
<dialog ref="editor" class="modal" @cancel.prevent="closeModal" @click="event=>{if(event.target===editor)closeModal()}"><template v-if="modal==='editor'"><div class="modal-header"><div><div class="overline green">A PAGE OF YOUR JOURNEY</div><h2>{{draft.id?'编辑旅行手记':'写下旅途中的小事'}}</h2></div><button class="close-modal" aria-label="关闭编辑器" @click="closeModal">×</button></div><form @submit.prevent="saveNote"><label class="form-label">手记标题<input v-model="draft.title" placeholder="给这段旅程起个名字" maxlength="80" required/></label><div class="form-row"><label class="form-label">目的地<select aria-label="目的地" v-model="draft.placeId"><option v-for="p in places" :key="p.id" :value="p.id">{{p.name}} · {{p.country}}</option></select></label><label class="form-label">旅行日期<input v-model="draft.date" type="date" required/></label></div><label class="form-label">旅途故事<textarea v-model="draft.body" placeholder="那天的风景、遇见的人、难忘的小事……从一句话开始吧。" rows="8" maxlength="20000" required></textarea></label><div class="form-bottom"><span>{{draft.body.length}} / 20000 字</span><span>仅保存在本机，支持导出备份</span></div><p v-if="formError" role="alert">{{formError}}</p><div class="modal-actions"><button type="button" class="button outline" @click="closeModal">取消</button><button class="button primary" type="submit">保存这段回忆 ↗</button></div></form></template><template v-else-if="modal==='about'"><div class="modal-header"><h2>关于山海漫游</h2><button class="close-modal" aria-label="关闭" @click="closeModal">×</button></div><div class="about-copy"><p>这是一本可以慢慢翻阅的旅行图鉴。以自然、古迹与人文为线索，收集六大洲 {{places.length}} 处目的地，也为你自己的旅行故事留一页空间。</p><p>景点介绍依据 UNESCO 世界遗产中心公开资料整理，使用 CC BY-SA 3.0 IGO 许可；标题与观察建议为编辑内容。每张实景照片来自 Wikimedia Commons，详情页保留原始文件、摄影者和相应许可。</p><p>省市分类为旅行浏览用途；跨国遗产可能合并显示或选择一侧展示，详情页有说明。页面不提供实时票价和开放时间。</p><p>收藏与手记存储在当前浏览器，不会自动上传或跨设备同步。可在“旅行手记”中导出及合并导入 JSON 备份。</p><a href="https://whc.unesco.org/en/list/" target="_blank" rel="noopener noreferrer">UNESCO 世界遗产名录 ↗</a><br/><a href="https://commons.wikimedia.org/" target="_blank" rel="noopener noreferrer">Wikimedia Commons ↗</a></div></template></dialog>
<Transition name="toast"><div v-if="toast" class="toast-message" role="status">✓ {{toast}}</div></Transition>
</template>
